//....oooOO0OOooo........oooOO0OOooo........oooOO0OOooo........oooOO0OOooo......

G4double PrimaryGeneratorAction::SampleEnergy()
{
  // Amostragem por histograma usando o método de transformação inversa
  G4double random = G4UniformRand();
  G4double cumulative = 0.0;

  for (size_t i = 0; i < fEnergyProbs.size(); ++i) {
    cumulative += fEnergyProbs[i];
    if (random <= cumulative) {
      // Amostrar uniformemente dentro do bin
      if (i < fEnergyBins.size() - 1) {
        G4double binWidth = fEnergyBins[i+1] - fEnergyBins[i];
        return (fEnergyBins[i] + G4UniformRand() * binWidth) * MeV;
      }
      return fEnergyBins[i] * MeV;
    }
  }

  // Fallback (não deveria chegar aqui)
  return fEnergyBins.back() * MeV;
}

//....oooOO0OOooo........oooOO0OOooo........oooOO0OOooo........oooOO0OOooo......

G4ThreeVector PrimaryGeneratorAction::SampleCosineDirection()
{

  G4double cosTheta = -std::sqrt(G4UniformRand());  // Cosine-law: [-1, 0]
  G4double sinTheta = std::sqrt(1.0 - cosTheta*cosTheta);
  G4double phi = 2.0 * CLHEP::pi * G4UniformRand();

  G4double ux = sinTheta * std::cos(phi);
  G4double uy = sinTheta * std::sin(phi);
  G4double uz = cosTheta;  // negativo (para baixo)

  return G4ThreeVector(ux, uy, uz);
}

//....oooOO0OOooo........oooOO0OOooo........oooOO0OOooo........oooOO0OOooo......

void PrimaryGeneratorAction::GeneratePrimaries(G4Event* anEvent)
{

  if (!fIon) {
      G4IonTable* ionTable = G4IonTable::GetIonTable();
      fIon = ionTable->GetIon(26, 56, 0.);

      fParticleGun->SetParticleDefinition(fIon);
  }

  // Amostrar posição no disco
  G4ThreeVector position(0.0, 0.0, fSourceZ);
  fParticleGun->SetParticlePosition(position);

  // Amostrar energia do espectro
  ///G4double energy = SampleEnergy();
  ///fParticleGun->SetParticleEnergy(energy);

  G4double energyPerNucleon = SampleEnergy();  // já vem em MeV
  G4int A = fParticleGun->GetParticleDefinition()->GetBaryonNumber();
  G4double totalEnergy = energyPerNucleon;

  if (A > 1) {
      totalEnergy = A * energyPerNucleon;
  }

  fParticleGun->SetParticleEnergy(totalEnergy);

  // Amostrar direção isotrópica para baixo
  G4ThreeVector direction = SampleCosineDirection();
  fParticleGun->SetParticleMomentumDirection(direction);

  // Gerar a partícula primária
  fParticleGun->GeneratePrimaryVertex(anEvent);

  // DEBUG primeiros 5 eventos
  if (anEvent->GetEventID() < 5) {
    G4cout << "\n==> Event " << anEvent->GetEventID() << ":" << G4endl;
    G4cout << "    Position: " << position/cm << " cm (POINT SOURCE)" << G4endl;
    G4cout << "    Energy: " << totalEnergy/MeV << " MeV (total), "
           << energyPerNucleon/MeV << " MeV/n" << G4endl;
    G4cout << "    Direction: " << direction
           << " (cosTheta=" << direction.z() << ")" << G4endl;
  }

}

